  t.equal((await send(without('x-chatmcp-csrf'), {})).status, 403, 'no CSRF token: 403');
  t.equal((await send({ ...page, 'x-chatmcp-csrf': 'f'.repeat(64) }, {})).status, 403, 'a wrong CSRF token: 403');
