  t.equal((await send({ ...page, 'content-type': 'text/plain' }, {})).status, 415, 'not JSON: 415');
  t.equal((await hub.rawRequest({ method: 'GET', route: ROUTE, headers: hub.authHeaders })).status, 404, 'a GET is not a route');
