    fs.writeFileSync(path.join(dir, STATE), JSON.stringify({ version: 1, latest: '3.10.2', checkedAt: new Date(Date.now() - 2 * 86_400_000).toISOString(), lastAttemptAt: new Date(Date.now() - 2 * 86_400_000).toISOString() }));
