  background-color: var(--bg);
  color: var(--text);
  font-size: 13px;
  line-height: 1.5;
  overflow: hidden;
}

/* 3D Motion and Interactive Depth System */
.perspective-container {
  perspective: 1200px;
}

.transform-style-3d {
  transform-style: preserve-3d;
}

.tilt-3d {
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s ease, border-color 0.2s ease;
  will-change: transform;
}

.tilt-3d:hover {
  transform: translateY(-1.5px);
  box-shadow: var(--shadow-3d);
}

.modal-3d-enter {
  animation: modalEnter3D 0.22s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  transform-origin: center top;
  backface-visibility: hidden;
  -webkit-font-smoothing: antialiased;
}

@keyframes modalEnter3D {
  from {
    opacity: 0;
    transform: perspective(1000px) translateY(-10px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: perspective(1000px) translateY(0) scale(1);
  }
}

.floating-step {
  box-shadow: 0 0 14px rgba(56, 189, 248, 0.25);
  animation: glowPulse 2.4s ease-in-out infinite alternate;
}

@keyframes glowPulse {
  0% {
    box-shadow: 0 0 6px rgba(56, 189, 248, 0.15);
    border-color: rgba(56, 189, 248, 0.3);
  }
  100% {
    box-shadow: 0 0 16px rgba(56, 189, 248, 0.35);
    border-color: rgba(56, 189, 248, 0.6);
  }
}

@media (prefers-reduced-motion: reduce) {
  .tilt-3d, .tilt-3d:hover, .modal-3d-enter, .floating-step {
    transform: none !important;
    animation: none !important;
    transition: none !important;
  }
}

/* Custom Scrollbars */
::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--line);
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--faint);
}

/* Code & monospace */
pre, code, .font-mono {
  font-family: "JetBrains Mono", "Cascadia Code", Consolas, monospace;
}

