     }
-    $resolvedRepo = Resolve-Path -LiteralPath $RepoRoot
-    if ($resolvedRepo.Provider.Name -ne 'FileSystem') {
-        throw 'RepoRoot must be a Windows filesystem folder.'
+    if ($chosenBackend -eq 'mcp') {
